SELECT percentile_cont(0.75) within GROUP (ORDER BY icustays.los) AS percentile_75 FROM admissions JOIN patients ON admissions.subject_id = patients.subject_id JOIN icustays ON admissions.stay_id = icustays.stay_id WHERE patients.gender = 'M' AND patients.anchor_age = 80 AND (icustays.los / (60 * 60 * 24))::FLOAT > 75 AND (icustays.los / (60 * 60 * 24))::FLOAT <= 85 AND EXISTS (SELECT 1 FROM diagnoses_icd WHERE diagnoses_icd.subject_id = admissions.subject_id AND diagnoses_icd.icd_code IN ('4280', '4281', '4282'));